def numOfWays(M, N):
	total = M * N
	total = M * N
	ans = 0
	for i in range(M):
		for j in range(N):
			temp = allAttackingPositions(i, j, M, N) + 1
			ans += total - temp
	return ans % 1000000007

def allAttackingPositions(i, j, M, N):
	dirs = [(2, 1), (2, -1), (-2, 1), (-2, -1), (-1, 2), (1, 2), (-1, -2), (1, -2)]
	count = 0
	for (x, y) in dirs:
		if isValid(i + x, j + y, M, N):
			count += 1
	return count

def isValid(x, y, M, N):
	return 0 <= x < M and 0 <= y < N
